import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  progress_completed INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  fingerprint TEXT,
  available_at INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
CREATE TABLE IF NOT EXISTS heartbeats (
  name TEXT PRIMARY KEY,
  at INTEGER NOT NULL
);
`;

/** Path of the SQLite file shared by the server and the worker. */
export function databasePath(): string {
  return process.env.DATABASE_PATH || 'data/jobs.db';
}

/** Opens the SQLite database shared by the server and worker processes and makes sure the schema exists. */
export function openDatabase(path: string = databasePath()): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL; PRAGMA synchronous = FULL;');
  db.exec(SCHEMA);
  return db;
}
/** Processing constants shared by the server and the worker. */
export const STEP_MS = 100;
export const RETRY_DELAY_MS = 500;
export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A job as returned by the API. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A row of the `jobs` table, as read from SQLite. */
export type JobRow = {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
};

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_ERROR, type JobRow } from './jobs.ts';

const HEARTBEAT_MS = 1000;
const IDLE_POLL_MS = 200;

const db = openDatabase();

const heartbeat = db.prepare(`
  INSERT INTO heartbeats (name, at) VALUES ('worker', ?)
  ON CONFLICT (name) DO UPDATE SET at = excluded.at`);
const clearHeartbeat = db.prepare("DELETE FROM heartbeats WHERE name = 'worker'");
// A job left "running" means an earlier worker died mid-attempt: put it back in the queue.
const requeueInterrupted = db.prepare(`
  UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ?
  WHERE status = 'running'`);
const nextQueued = db.prepare(`
  SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1`);
const claim = db.prepare(`
  UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
  WHERE id = ? AND status = 'queued'`);
const setProgress = db.prepare(`
  UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
const complete = db.prepare(`
  UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ?
  WHERE id = ? AND status = 'running'`);
const requeue = db.prepare(`
  UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ?
  WHERE id = ? AND status = 'running'`);
const fail = db.prepare(`
  UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = ?, updated_at = ?
  WHERE id = ? AND status = 'running'`);

let stopping = false;
const stop = (): void => {
  stopping = true;
};
process.on('SIGTERM', stop);
process.on('SIGINT', stop);

const nowIso = (): string => new Date().toISOString();

function beat(): void {
  heartbeat.run(Date.now());
}

/** Runs one attempt of a claimed job. Returns early, leaving the job running, if the worker is stopping. */
async function runAttempt(job: JobRow, attempt: number): Promise<void> {
  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: fails at the first step, before any progress.
    await sleep(STEP_MS);
    if (attempt >= MAX_ATTEMPTS) fail.run(TRANSIENT_ERROR, nowIso(), job.id);
    else requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress.run(step, nowIso(), job.id);
  }
  complete.run(job.input.toUpperCase(), nowIso(), job.id);
}

async function main(): Promise<void> {
  requeueInterrupted.run(Date.now(), nowIso());
  beat();
  const timer = setInterval(beat, HEARTBEAT_MS);

  console.log('worker started');
  while (!stopping) {
    const job = nextQueued.get(Date.now()) as JobRow | undefined;
    if (!job) {
      await sleep(IDLE_POLL_MS);
      continue;
    }
    const claimed = claim.run(nowIso(), job.id);
    if (Number(claimed.changes) === 0) continue;
    await runAttempt(job, job.attempts + 1);
  }

  clearInterval(timer);
  clearHeartbeat.run();
  db.close();
  console.log('worker stopped');
  process.exit(0);
}

main().catch((e: unknown) => {
  console.error('worker failed:', e);
  process.exit(1);
});
export interface FieldError {
  field: string;
  message: string;
}

export interface JobInput {
  input: string;
  steps: number;
  failAttempts: number;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
export const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function integerIn(value: unknown, min: number, max: number): boolean {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Validates a parsed request body. Returns the job parameters with defaults applied, or every field error. */
export function validateJobBody(body: unknown): { value: JobInput } | { fields: FieldError[] } {
  if (!isPlainObject(body)) return { fields: [{ field: 'body', message: 'body must be a JSON object' }] };

  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  const { input, steps = 5, failAttempts = 0 } = body;

  let validInput: string | undefined;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'input is required' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'input must not be blank' });
  } else {
    validInput = input;
  }

  if (!integerIn(steps, 1, 20)) fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
  if (!integerIn(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });

  if (fields.length > 0 || validInput === undefined) return { fields };
  return { value: { input: validInput, steps: steps as number, failAttempts: failAttempts as number } };
}

/** Validates the Idempotency-Key header. Returns a field error, or undefined when valid or absent. */
export function validateIdempotencyKey(key: string | undefined): FieldError | undefined {
  if (key === undefined || IDEMPOTENCY_KEY_RE.test(key)) return undefined;
  return { field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' };
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { toJob, type Job, type JobRow } from './jobs.ts';
import { validateIdempotencyKey, validateJobBody, type FieldError, type JobInput } from './validation.ts';

const MAX_BODY_BYTES = 64 * 1024;
/** The worker counts as up if its heartbeat is at most this old. */
const WORKER_STALE_MS = 3000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const insertJob = db.prepare(`
  INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, result_output, error,
                    idempotency_key, fingerprint, available_at, created_at, updated_at)
  VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, ?, ?)`);
const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectHeartbeat = db.prepare('SELECT at FROM heartbeats WHERE name = ?');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields === undefined ? { code, message } : { code, message, fields } });
}

function sendInvalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

/** Reads the request body as text. Resolves to null when the body is larger than MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  if (header === undefined) return false;
  return header.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

function nowIso(): string {
  return new Date().toISOString();
}

/** Inserts a job. Runs inside a transaction when an idempotency key is given, so a key never yields two jobs. */
function createJob(params: JobInput, key: string | undefined): { created: boolean; row: JobRow; conflict: boolean } {
  const fingerprint = key === undefined ? null : JSON.stringify([params.input, params.steps, params.failAttempts]);
  const insert = (): JobRow => {
    const id = randomUUID();
    const now = nowIso();
    insertJob.run(id, params.input, params.steps, params.failAttempts, key ?? null, fingerprint, Date.now(), now, now);
    return selectById.get(id) as JobRow;
  };
  if (key === undefined) return { created: true, row: insert(), conflict: false };

  db.exec('BEGIN IMMEDIATE');
  try {
    const existing = selectByKey.get(key) as (JobRow & { fingerprint: string | null }) | undefined;
    let result: { created: boolean; row: JobRow; conflict: boolean };
    if (existing) {
      result = { created: false, row: existing, conflict: existing.fingerprint !== fingerprint };
    } else {
      result = { created: true, row: insert(), conflict: false };
    }
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

async function handlePostJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const keyHeader = req.headers['idempotency-key'];
  const key = typeof keyHeader === 'string' ? keyHeader : undefined;
  const fields: FieldError[] = [];
  const keyError = validateIdempotencyKey(key);
  if (keyError) fields.push(keyError);

  const raw = await readBody(req);
  if (raw === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
    return sendInvalid(res, fields);
  }
  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return sendInvalid(res, fields);
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    fields.push({ field: 'body', message: 'body is not valid JSON' });
    return sendInvalid(res, fields);
  }

  const validated = validateJobBody(parsed);
  if (!('value' in validated)) {
    fields.push(...validated.fields);
    return sendInvalid(res, fields);
  }
  if (fields.length > 0) return sendInvalid(res, fields);

  const result = createJob(validated.value, key);
  if (result.conflict) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, result.created ? 201 : 200, toJob(result.row));
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = selectById.get(id) as JobRow | undefined;
  if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
  send(res, 200, toJob(row));
}

function handleList(res: ServerResponse): void {
  const rows = selectAll.all() as unknown as JobRow[];
  const jobs: Job[] = rows.map(toJob);
  send(res, 200, { jobs });
}

function handleHealth(res: ServerResponse): void {
  const beat = selectHeartbeat.get('worker') as { at: number } | undefined;
  const up = beat !== undefined && Date.now() - Number(beat.at) <= WORKER_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  send(res, 405, { error: { code: 'method_not_allowed', message: `Method not allowed. Use ${allowed.join(', ')}.` } }, { allow: allowed.join(', ') });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') return method === 'GET' ? handleHealth(res) : methodNotAllowed(res, ['GET']);
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleList(res);
    if (method === 'POST') return handlePostJob(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) return method === 'GET' ? handleGetJob(res, match[1]!) : methodNotAllowed(res, ['GET']);
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
