<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form" novalidate>
    <label>Input
      <input data-testid="job-input" name="input" type="text" autocomplete="off">
    </label>
    <label>Steps
      <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" value="5">
    </label>
    <label>Fail attempts
      <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" value="0">
    </label>
    <button data-testid="job-submit" type="submit">Submit job</button>
  </form>

  <div data-testid="form-error" role="alert" id="form-error"></div>

  <ul data-testid="job-list" id="job-list" aria-label="Jobs"></ul>

  <script>
    const form = document.getElementById('job-form');
    const inputEl = form.elements.namedItem('input');
    const stepsEl = form.elements.namedItem('steps');
    const failEl = form.elements.namedItem('failAttempts');
    const submitBtn = document.querySelector('[data-testid="job-submit"]');
    const errorEl = document.getElementById('form-error');
    const listEl = document.getElementById('job-list');

    // Numeric-looking text becomes a number; anything else is sent as text so the API rejects it.
    // An empty field is omitted so the API default applies.
    function fieldValue(text) {
      const t = text.trim();
      if (t === '') return undefined;
      return /^-?\d+(\.\d+)?$/.test(t) ? Number(t) : text;
    }

    function describeRejection(status, data) {
      const err = data && data.error;
      if (!err) return 'Request failed with status ' + status + '.';
      const fields = Array.isArray(err.fields) && err.fields.length
        ? err.fields.map((f) => f.field + ': ' + f.message).join('\n')
        : '';
      return err.message + (fields ? '\n' + fields : '');
    }

    function renderJob(job) {
      const li = document.createElement('li');
      li.setAttribute('data-testid', 'job-item');
      li.dataset.jobId = job.id;

      const status = document.createElement('span');
      status.setAttribute('data-testid', 'job-status');
      status.className = 'status-' + job.status;
      status.textContent = job.status;

      const progress = document.createElement('span');
      progress.setAttribute('data-testid', 'job-progress');
      progress.textContent = job.progress.completed + '/' + job.progress.total;

      const result = document.createElement('span');
      result.setAttribute('data-testid', 'job-result');
      if (job.status === 'completed' && job.result) result.textContent = job.result.output;
      else if (job.status === 'failed') result.textContent = job.error || '';

      const id = document.createElement('span');
      id.className = 'id';
      id.textContent = job.input + '  (' + job.id + ', attempts: ' + job.attempts + ')';

      li.append(status, progress, result, id);
      return li;
    }

    async function refresh() {
      try {
        const res = await fetch('/api/jobs', { cache: 'no-store' });
        if (!res.ok) return;
        const data = await res.json();
        listEl.replaceChildren(...data.jobs.map(renderJob));
      } catch {
        // Keep the last list on screen; the next poll retries.
      }
    }

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      errorEl.textContent = '';
      const body = { input: inputEl.value };
      const steps = fieldValue(stepsEl.value);
      const failAttempts = fieldValue(failEl.value);
      if (steps !== undefined) body.steps = steps;
      if (failAttempts !== undefined) body.failAttempts = failAttempts;

      submitBtn.disabled = true;
      try {
        const res = await fetch('/api/jobs', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        });
        const data = await res.json().catch(() => null);
        if (res.status === 201 || res.status === 200) {
          inputEl.value = '';
          await refresh();
        } else {
          errorEl.textContent = describeRejection(res.status, data);
        }
      } catch (err) {
        errorEl.textContent = 'Could not reach the server: ' + err.message;
      } finally {
        submitBtn.disabled = false;
      }
    });

    refresh();
    setInterval(refresh, 1000);
  </script>
